// The localized description, failure reason and recovery suggestion of NSError for NSCocoaErrorDomain codes and
// a few codes of NSPOSIXErrorDomain, NSOSStatusErrorDomain, NSMachErrorDomain and NSURLErrorDomain, with and
// without NSFilePathErrorKey, NSURLErrorKey, NSStringEncodingErrorKey, NSUnderlyingErrorKey,
// NSLocalizedDescriptionKey and NSLocalizedFailureReasonErrorKey in the userInfo.
//
// The expected strings are black-box observations of macOS 10.14.4 (x86_64 and i386, identical) made with
// mac-probes/cocoa-error-descriptions/cocoa-errors.m (results.10.14.4-*.txt there); macOS 26.7.3 gives the same
// strings except for a recovery suggestion of code 4354 (spelled "iCloud settings"), and has one more code, 4102.
// Following the older system, Mojave's strings are the contract here. A variant that is not listed for a code gives
// what the code gives without userInfo. {VOLUME} stands for the name of the volume that holds /tmp, which the
// text of a few codes names. Runs in the guest without a window server.
#import <Foundation/Foundation.h>
#include <stdio.h>

typedef struct {
    NSString *domain;
    long code;
    NSString *variant;
    NSString *description, *reason, *suggestion; // nil: the property is nil
} Row;

