static NSDictionary *userInfoFor(NSString *variant) {
    NSString *path = @"/tmp/some folder/example.txt";
    NSURL *url = [NSURL fileURLWithPath:path];
    NSError *under = [NSError errorWithDomain:NSPOSIXErrorDomain code:2 userInfo:nil];
    if ([variant isEqual:@"none"]) return nil;
    if ([variant isEqual:@"path"]) return @{NSFilePathErrorKey: path};
    if ([variant isEqual:@"url"]) return @{NSURLErrorKey: url};
    if ([variant isEqual:@"path+url"]) return @{NSFilePathErrorKey: path, NSURLErrorKey: url};
    if ([variant isEqual:@"encoding"]) return @{NSStringEncodingErrorKey: @(NSUTF8StringEncoding)};
    if ([variant isEqual:@"underlying"]) return @{NSUnderlyingErrorKey: under};
    if ([variant isEqual:@"path+underlying"]) return @{NSFilePathErrorKey: path, NSUnderlyingErrorKey: under};
    if ([variant isEqual:@"description-key"]) return @{NSLocalizedDescriptionKey: @"Given description"};
    if ([variant isEqual:@"reason-key"]) return @{NSLocalizedFailureReasonErrorKey: @"Given reason."};
    if ([variant isEqual:@"url-http"]) return @{NSURLErrorKey: [NSURL URLWithString:@"http://example.com/dir/page.html"]};
    if ([variant isEqual:@"path-rel"]) return @{NSFilePathErrorKey: @"example.txt"};
    if ([variant isEqual:@"path-dir"]) return @{NSFilePathErrorKey: @"/tmp/some folder/"};
    if ([variant isEqual:@"path-empty"]) return @{NSFilePathErrorKey: @""};
    if ([variant isEqual:@"url-dir"]) return @{NSURLErrorKey: [NSURL fileURLWithPath:@"/tmp/some folder" isDirectory:YES]};
    if ([variant isEqual:@"path-ext-hidden"]) return @{NSFilePathErrorKey: @"/tmp/archive.tar.gz"};
    if ([variant isEqual:@"validation-key"]) return @{@"NSValidationKey": @"name", @"NSValidationValue": @"v"};
    return nil;
}


int main(void) {
    int failures = 0, checks = 0;
    @autoreleasepool {
        id volumeName = nil;
        [[NSURL fileURLWithPath:@"/tmp" isDirectory:YES] getResourceValue:&volumeName forKey:NSURLVolumeNameKey error:NULL];
        NSString *volume = [volumeName isKindOfClass:[NSString class]] ? volumeName : @"";
        NSArray *variants = @[@"none", @"path", @"url", @"path+url", @"path-rel", @"path-dir", @"url-dir", @"path-ext-hidden", @"url-http",
                              @"encoding", @"underlying", @"path+underlying", @"description-key", @"reason-key", @"path-empty", @"validation-key"];
        NSMutableOrderedSet *keys = [NSMutableOrderedSet orderedSet];
        for (size_t i = 0; i < sizeof rows / sizeof rows[0]; i++)
            [keys addObject:[NSString stringWithFormat:@"%@ %ld", rows[i].domain, rows[i].code]];
        for (NSString *key in keys) {
            NSArray *parts = [key componentsSeparatedByString:@" "];
            NSString *domain = parts[0];
            long code = [parts[1] longLongValue];
            const Row *none = NULL;
            for (size_t i = 0; i < sizeof rows / sizeof rows[0]; i++)
                if ([rows[i].domain isEqual:domain] && rows[i].code == code && [rows[i].variant isEqual:@"none"]) none = &rows[i];
            for (NSString *variant in variants) {
                const Row *expected = none;
                for (size_t i = 0; i < sizeof rows / sizeof rows[0]; i++)
                    if ([rows[i].domain isEqual:domain] && rows[i].code == code && [rows[i].variant isEqual:variant]) expected = &rows[i];
                NSError *e = [NSError errorWithDomain:domain code:code userInfo:userInfoFor(variant)];
                NSString *got[3] = { [e localizedDescription], [e localizedFailureReason], [e localizedRecoverySuggestion] };
                NSString *want[3] = { expected->description, expected->reason, expected->suggestion };
                const char *names[3] = { "description", "failure reason", "recovery suggestion" };
                for (int p = 0; p < 3; p++) {
                    NSString *w = want[p] ? [want[p] stringByReplacingOccurrencesOfString:@"{VOLUME}" withString:volume] : nil;
                    checks++;
                    if (!(w == nil ? got[p] == nil : [w isEqual:got[p]])) {
                        failures++;
                        if (failures <= 40)
                            printf("FAIL %s %ld %s %s: got \"%s\", expected \"%s\"\n", [domain UTF8String], code, [variant UTF8String], names[p],
                                   got[p] ? [got[p] UTF8String] : "(nil)", w ? [w UTF8String] : "(nil)");
                    }
                }
            }
        }
    }
    printf("%d checks, %d failures\n", checks, failures);
    printf(failures ? "FAIL\n" : "PASS\n");
    return failures != 0;
}
